<style>
.learning-shell{width:min(1480px,calc(100% - 34px));margin:auto;display:grid;grid-template-columns:250px minmax(0,1fr) 270px;gap:24px;align-items:start;padding:38px 0 70px}.learning-sidebar{position:sticky;top:20px;max-height:calc(100vh - 40px);overflow:auto;border:1px solid #dbe5f0;border-radius:16px;background:#fff;box-shadow:0 10px 30px rgba(15,39,71,.06)}.sidebar-title{padding:19px 18px 14px;border-bottom:1px solid #edf2f7}.sidebar-title h2{margin:5px 0 0;font-size:18px;color:#10213e}.sidebar-kicker{color:#2563eb;font-size:10px;font-weight:850;letter-spacing:1.2px}.sidebar-links,.other-course-links{display:grid;gap:7px;padding:12px}.sidebar-links a{display:grid;grid-template-columns:28px 1fr;gap:2px 9px;padding:11px;border-radius:10px;color:#43536a;text-decoration:none}.sidebar-links a>span{grid-row:1/3;display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:#edf3fb;color:#56708e;font-size:11px;font-weight:800}.sidebar-links b{font-size:13px;line-height:1.35}.sidebar-links small{color:#8795a8;font-size:10px}.sidebar-links a:hover{background:#f3f7fc}.sidebar-links a.active{background:#eaf2ff;color:#174ea6}.sidebar-links a.active>span{background:#2563eb;color:#fff}.other-course-links a{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid #e8edf4;border-radius:11px;color:#26364d;text-decoration:none;transition:.18s}.other-course-links a:hover{transform:translateX(2px);border-color:var(--course-color);background:#f8fbff}.course-icon{display:grid;place-items:center;width:39px;height:39px;flex:none;border-radius:10px;background:color-mix(in srgb,var(--course-color) 13%,white);color:var(--course-color);font-size:11px;font-weight:900}.other-course-links a>span:nth-child(2){display:grid;flex:1}.other-course-links b{font-size:13px}.other-course-links small{margin-top:3px;color:#8795a8;font-size:10px}.other-course-links i{color:var(--course-color);font-style:normal}.all-courses-link{display:block;margin:0 12px 14px;padding:11px;text-align:center;border-radius:9px;background:#10213e;color:#fff;text-decoration:none;font-size:12px;font-weight:800}.questions-main{min-width:0}.question-pagination{display:flex;align-items:center;justify-content:center;gap:7px;flex-wrap:wrap;margin-top:25px}.question-pagination a,.question-pagination span{display:grid;place-items:center;min-width:40px;height:40px;padding:0 11px;border:1px solid #d9e3ef;border-radius:9px;background:#fff;color:#26415f;text-decoration:none;font-weight:750}.question-pagination .active{border-color:#2563eb;background:#2563eb;color:#fff}.question-pagination .disabled{color:#9ba8b8;background:#f4f6f9}.page-summary{text-align:center;margin:14px 0 0;color:#718096;font-size:13px}@media(max-width:1100px){.learning-shell{grid-template-columns:220px minmax(0,1fr)}.course-sidebar{position:static;grid-column:1/-1;max-height:none}.other-course-links{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.learning-shell{grid-template-columns:1fr;padding-top:22px}.learning-sidebar{position:static;max-height:none}.topic-sidebar .sidebar-links{grid-template-columns:repeat(2,minmax(0,1fr))}.course-sidebar{grid-column:auto}.other-course-links{grid-template-columns:1fr}}@media(max-width:480px){.learning-shell{width:min(100% - 22px,1480px)}.topic-sidebar .sidebar-links{grid-template-columns:1fr}}
</style>
